/// <summary>
/// MPJ_28779 Item MDR 26/08/2022
/// </summary>
[ExtensionOf(formDataSourceStr(HMIMItemMaterialList, HMIMItemMaterial))]
final class METHMIMItemMaterialFormDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource              metHMIMItemMaterial_ds;
        METHMIMItemMaterial         metHMIMItemMaterial;
        HMIMItemMaterial            hmimItemMaterial;

        next write();

        metHMIMItemMaterial_ds = this.formRun().dataSource(formDataSourceStr(HMIMItemMaterialList, METHMIMItemMaterial));

        if (metHMIMItemMaterial_ds)
        {
            hmimItemMaterial      = this.cursor();
            metHMIMItemMaterial   = metHMIMItemMaterial_ds.cursor();
            
            hmimItemMaterial.metPackMETHMIMItemMaterial(metHMIMItemMaterial);
            metHMIMItemMaterial.SysExtensionSerializerExtensionMap::insertAfterBaseTable(hmimItemMaterial);
        }

    }
